import { Grid, Paper, TextField, Typography, Link } from "@mui/material";
import React, { useState } from 'react';
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';
import Button from '@mui/material/Button';
//import { blue } from "@mui/material/colors";
import { useNavigate } from "react-router-dom";
import dayjs from 'dayjs';
import { DemoContainer, DemoItem } from '@mui/x-date-pickers/internals/demo';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';

const todayAtNoon = dayjs().set('hour', 12).startOf('hour');
const todayAt3PM = dayjs().set('hour', 15).startOf('hour');

const Sign = () => {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [name, setName] = useState('');
    const [password, setPassword] = useState('');
    const [emailError, setEmailError] = useState();
    const [nameError, setNameError] = useState();
    const [passwordError, setPasswordError] = useState();
    const [confirmPassword, setConfirmPassword] = useState('');
    const [confirmPasswordError, setConfirmPasswordError] = useState();
    const handleEmailChange = (e) => {
        setEmail(e.target.value)
        if (!validateEmail(e.target.value)) {
            setEmailError("please enter valid email");
        }
        else {
            setEmailError("");
        };
    };
    const handleNameChange = (e) => {
        setName(e.target.value)
        if (e.target.value.length ) {
            setNameError("please enter valid name");
        }
        else {
            setNameError("");
        };
    };

    const validateEmail = (email) => {
        const emailRegex = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{3,5}$/i;
        return emailRegex.test(email)
    }

    const handlePasswordChange = (e) => {
        setPassword(e.target.value)
        if (e.target.value.length < 6) {
            setPasswordError("Password must be atleast 6 characters");
        }
        else {
            setPasswordError("");
        }
    };
    const handleConfirmPasswordChange = (e) => {
        setConfirmPassword(e.target.value)
        if (e.target.value.length < 6) {
            setConfirmPasswordError("Password must be atleast 6 characters");
        }
        else if (e.target.value !== password) {
            setConfirmPasswordError("Password do not match");
        }
        else {
            setConfirmPasswordError("");
        }
    }

    const handleSubmit = (e) => {
        e.preventDefault();
        if (email &&name&& password && confirmPassword && !(emailError) && !(passwordError) && !(nameError) && !(confirmPasswordError))
            alert("account create successfuly");
        navigate("https://accounts.google.com/SignOutOptions?hl=en-GB&continue=https://www.google.com%3Fhl%3Den-GB&ec=GBRA8wE", { replace: true })

    }
    const paperStyle = { padding: 20, height: "80vh", width: 290, margin: "22px auto", }
    const btnStyle = { margin: "12px 0px" }
    return (
        <div>
            <form onSubmit={handleSubmit} >
                <Grid>
                    <Paper elevation={10} sx={{ bgcolor: "goldenrod" }} style={paperStyle} >
                        <Grid align="center">
                            <h1> signUp</h1>
                        </Grid >
                        <TextField label="Name" variant="standard" placeholder="Enter Your Name " onChange={handleNameChange}
                            value={name}
                            error={nameError} fullWidth required />
                        <TextField label="Email" variant="standard" placeholder="Enter useremail " onChange={handleEmailChange}
                            value={email}
                            error={emailError} fullWidth required />
                        <TextField label="Password" variant="standard" placeholder="Enter password " type="password"
                            onChange={handlePasswordChange}
                            value={password}
                            error={passwordError} fullWidth required />
                        <TextField label="confirm Password" variant="standard" placeholder="Enter confirmpassword " type="confirm password"
                            onChange={handleConfirmPasswordChange}
                            value={confirmPassword}
                            error={confirmPasswordError} fullWidth required />
                     <Typography sx={{width:"250px",height:"100px"}}>
                        <LocalizationProvider   dateAdapter={AdapterDayjs} >
                            <DemoContainer  components={['DateTimePicker']}>
                                <DemoItem label="Date Of birth & Time">
                                    <DateTimePicker defaultValue={todayAtNoon} minDateTime={todayAt3PM} />
                                </DemoItem>
                            </DemoContainer>
                        </LocalizationProvider>
                        </Typography>

                        <FormControlLabel required control={<Checkbox />} label="Required" />
                        <Button type="submit"
                            variant="contained" color="success" style={btnStyle}
                            fullWidth label="Required"  >
                            sign in
                        </Button>
                        <br />


                        <Typography>
                            <Link href="#" >
                                Forget password ?
                            </Link>
                        </Typography>
                        <Typography> do you have an account ?
                            <Link href="/" >
                                Login ?
                            </Link>
                        </Typography>
                    </Paper>
                </Grid>
            </form>
        </div>
    )
}

export default Sign;