import React, { useState } from "react";
import MenuIcon from '@mui/icons-material/Menu';
import Logo from "../../images/logo.png"
import { Box } from "@mui/system";
import { AppBar, Divider, Drawer, IconButton, Toolbar, Typography } from "@mui/material";
import { NavLink } from "react-router-dom";
import "../../Styles/HeaderStyles.css";
const Header = () => {
  const [mobileOpen, setMobileOpen] = useState(false)
  //Handel menu
  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen)
  }
  
  const drawer = (
    <Box onClick={handleDrawerToggle} sx={{ textAline: 'center' }}>
      <Typography color={"goldenrod"} variant="h6" component="div" sx={{ flexGrow: 1, my: 2 }} >
        <img src={Logo} alt="logo" height={"30"} width="40"/>
        My resturent
      </Typography>
      <Divider />
      <ul className="mobile-navigation">
        <li>
          <NavLink activeClassName="active" to={"/home"}>Home</NavLink>
        </li>
        <li>
          <NavLink activeClassName="active" to={"/"}>Login</NavLink>
        </li>
        <li>
          <NavLink activeClassName="active" to={"/menu"}>Menu</NavLink>
        </li>
        <li>
          <NavLink activeClassName="active" to={"/about"}>About</NavLink>
        </li>
        <li>
          <NavLink activeClassName="active" to={"/contact"}>Contact</NavLink>
        </li>
      </ul>
    </Box>
  )
  return (
    <div>
     <Box>
        < AppBar component={"nav"} sx={{ bgcolor: " black " }}>
          <Toolbar >
            <IconButton size="large"
              edge="start"
              color="inherit"
              aria-label="open drawer"
              sx={{ mr: 2, display: { sm: "none" } }}
              onClick={handleDrawerToggle}
            >
              <MenuIcon />
            </IconButton>
            <Typography color={"goldenrod"} variant="h5" component="div" sx={{ flexGrow: 1 }} >
              <img src={Logo} alt="logo" height={"20"} width="40" />
              My resturent
            </Typography>
            <Box sx={{ display: { xs: "none", sm: "block" } }}>
              <ul className="Navigation-menu">
              <li>
               <NavLink activeClassName="active"  to={"/"}>Login</NavLink>
            </li>
                <li>
                  <NavLink activeClassName="active" to={"/home"}>Home</NavLink>
                </li>
                <li>
                  <NavLink activeClassName="active" to={"/menu"}>Menu</NavLink>
                </li>
                <li>
                  <NavLink activeClassName="active" to={"/about"}>About</NavLink>
                </li>
                <li>
                  <NavLink activeClassName="active" to={"/contact"}>Contact</NavLink>
                </li>
              </ul>
            </Box>
          </Toolbar>
        </AppBar>
        <Box component={"nav"}>
          <Drawer variant="temporary" open={mobileOpen} onClose={handleDrawerToggle}
            sx={{
              display: { xs: "Block", sm: "none" }, "& .MuiDrawer-paper": {
                boxSizing: "border-box",
                width: "250px",
              }
            }}
          >
            {drawer}
          </Drawer>
        </Box>
        <Box >
          <Toolbar />
        </Box>
      </Box>
    </div>
  )
}

export default Header;
